113	func TestApplyGoesPendingWithoutFreezing(t *testing.T) {
114		w, c := setupApproval(t)
115	
116		in := approvalApply()
117		req, err := w.Apply(in)
118		if err != nil {
119			t.Fatal(err)
120		}
121		if req.State != RequestPendingApproval {
122			t.Fatalf("state = %v, want pending approval", req.State)
123		}
124		// 等待期限 = min(提交+1分钟, 策略结束, 会话到期) = 提交+1分钟。
125		wantDeadline := c.t.Add(time.Minute)
126		if !req.WaitDeadline.Equal(wantDeadline) {
127			t.Fatalf("wait deadline = %v, want %v", req.WaitDeadline, wantDeadline)
128		}
129		if req.DecidedAt != (time.Time{}) || req.ApproverAccountID != "" || req.RejectReason != "" {
130			t.Fatalf("pending request should have no decision yet: %+v", req)
131		}
132	
133		// 待审批不冻结余额、不占用共享累计额度。
134		bal, _ := w.Balance("payer")
135		if bal != (Balances{Available: 100, Reserved: 0}) {
136			t.Fatalf("balance = %+v, want untouched {100 0}", bal)
137		}
138		pv, _ := w.Policy("p-approval")
139		if pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
140			t.Fatalf("policy totals = reserved %d spent %d, want 0/0", pv.ReservedTotal, pv.SpentTotal)
141		}
142		if len(w.AccountLedger("payer")) != 0 {
143			t.Fatal("pending approval must not create money-moving ledger entries")
144		}
145	
146		// 账本含待审批状态留痕，关联使用账户与请求号。
147		var found bool
148		for _, e := range w.Ledger() {
149			if e.Kind == LedgerPendingApproval {
150				found = true
151				if e.AccountID != "u1" || e.RequestID != "r1" || e.Amount != 0 {
152					t.Fatalf("pending ledger entry = %+v", e)
153				}
154			}
155		}
156		if !found {
157			t.Fatal("missing LedgerPendingApproval entry")
158		}
159	
160		// 等于门槛的费用直接预留，不进入待审批。
161		eq := approvalApply()
162		eq.RequestID = "r-eq"
163		eq.EstimatedFee = 10
164		eqReq, err := w.Apply(eq)
165		if err != nil {
166			t.Fatal(err)
167		}
168		if eqReq.State != RequestReserved {
169			t.Fatalf("fee equal to threshold state = %v, want reserved", eqReq.State)
170		}
171		// 低于门槛直接预留。
172		low := approvalApply()
173		low.RequestID = "r-low"
174		low.EstimatedFee = 9
175		lowReq, err := w.Apply(low)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if lowReq.State != RequestReserved {
180			t.Fatalf("fee below threshold state = %v, want reserved", lowReq.State)
181		}
182	}
