184	func TestApproveHappyPath(t *testing.T) {
185		w, _ := setupApproval(t)
186	
187		if _, err := w.Apply(approvalApply()); err != nil {
188			t.Fatal(err)
189		}
190		req, err := w.Approve("u1", "r1", "sa", "dev-approve")
191		if err != nil {
192			t.Fatal(err)
193		}
194		if req.State != RequestReserved {
195			t.Fatalf("state = %v, want reserved", req.State)
196		}
197		if req.ApproverAccountID != "payer" || req.DecidedAt.IsZero() {
198			t.Fatalf("approval decision fields missing: %+v", req)
199		}
200	
201		// 批准时一次性预留全部预估费用。
202		bal, _ := w.Balance("payer")
203		if bal != (Balances{Available: 80, Reserved: 20}) {
204			t.Fatalf("balance = %+v, want {80 20}", bal)
205		}
206		pv, _ := w.Policy("p-approval")
207		if pv.ReservedTotal != 20 || pv.SpentTotal != 0 {
208			t.Fatalf("policy totals = %+v", pv)
209		}
210	
211		// 账本：一条预留（资金）+ 一条批准（状态）。
212		var reserve, approval bool
213		for _, e := range w.Ledger() {
214			switch e.Kind {
215			case LedgerReserve:
216				reserve = true
217				if e.AccountID != "payer" || e.Amount != 20 || e.RequestID != "r1" {
218					t.Fatalf("reserve entry = %+v", e)
219				}
220			case LedgerApproval:
221				approval = true
222				if e.AccountID != "u1" || e.Amount != 0 || e.RequestID != "r1" {
223					t.Fatalf("approval entry = %+v", e)
224				}
225			}
226		}
227		if !reserve || !approval {
228			t.Fatalf("ledger missing reserve=%v approval=%v", reserve, approval)
229		}
230	
231		// 批准后可正常结算。
232		if _, err := w.Settle("u1", "r1", 8); err != nil {
233			t.Fatal(err)
234		}
235		bal, _ = w.Balance("payer")
236		if bal != (Balances{Available: 92, Reserved: 0}) {
237			t.Fatalf("balance after settle = %+v, want {92 0}", bal)
238		}
239	}
