290			t.Fatal(err)
291		}
292		if _, err := w.CreateSession("sa", "payer", "dev-approve", c.t.Add(time.Hour)); err != nil {
293			t.Fatal(err)
294		}
295		p := approvalPolicy(c)
296		p.MaxTotal = 200 // 允许连续预留以降低余额
297		if err := w.SavePolicy(p); err != nil {
298			t.Fatal(err)
