300	
301		in := approvalApply()
302		if _, err := w.Apply(in); err != nil {
303			t.Fatal(err)
304		}
305		// 连续预留 9 笔各 10，把出资余额降到 10（< 待审批费用 20）。
306		for i := 0; i < 9; i++ {
307			reserved := approvalApply()
308			reserved.RequestID = fmt.Sprintf("drop%d", i)
309			reserved.EstimatedFee = 10
310			if _, err := w.Apply(reserved); err != nil {
311				t.Fatal(err)
312			}
313		}
314		bal, _ := w.Balance("payer")
315		if bal.Available != 10 {
316			t.Fatalf("available = %d, want 10", bal.Available)
