318		// 批准时余额不足：返回具体原因，保留待审批状态。
319		if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); !errors.Is(err, ErrInsufficientBalance) {
320			t.Fatalf("err = %v, want ErrInsufficientBalance", err)
321		}
322		req, _ := w.Request("u1", "r1")
