324			t.Fatalf("state = %v, want still pending", req.State)
325		}
326		// 期限内可再次批准（余额仍不足则仍失败）。
327		if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); !errors.Is(err, ErrInsufficientBalance) {
328			t.Fatalf("second approve err = %v, want ErrInsufficientBalance", err)
329		}
330	}
